'use strict';

const { runCommand } = require('./_api_runner.cjs');

const OPTION_SPECS = [
  {
    "type": "boolean_flag",
    "flag": "--help",
    "keys": [
      "help"
    ]
  },
  {
    "type": "value",
    "flag": "--env",
    "keys": [
      "env"
    ]
  },
  {
    "type": "boolean_flag",
    "flag": "--verbose",
    "keys": [
      "verbose"
    ]
  },
  {
    "type": "boolean_flag",
    "flag": "--reload",
    "keys": [
      "reload"
    ]
  },
  {
    "type": "repeatable_value",
    "flag": "--header",
    "keys": [
      "header",
      "headers",
      "extraHeaders"
    ]
  }
];

async function runMtssoConfigs(params = {}, runtimeOptions = {}) {
  return runCommand({
    scriptRelativePath: 'scripts/mtsso_configs.js',
    params,
    optionSpecs: OPTION_SPECS,
    runtimeOptions,
  });
}

module.exports = {
  runMtssoConfigs,
};
module.exports.default = runMtssoConfigs;
